def count_nums(arr):
    def digit_sum(n):
        if n == 0:
            return 0
        total = 0
        negative = n < 0
        n = abs(n)
        # Process digits from least significant to most significant
        # The first signed digit (most significant) gets the sign
        # We need to find the most significant digit separately
        digits = []
        while n > 0:
            digits.append(n % 10)
            n //= 10
        digits.reverse()  # Now digits[0] is most significant

        for i, d in enumerate(digits):
            if i == 0 and negative:
                total -= d
            else:
                total += d
        return total

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1
    return count
```

