def fib4(n: int):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the first four terms
    fib = [0, 0, 2, 0]

    for i in range(4, n + 1):
        next_val = fib[i-1] + fib[i-2] + fib[i-3] + fib[i-4]
        fib.append(next_val)

    return fib[n]
```

